solution:
class Money:
    count = 0

    def __init__(self, cents):
        self.cents = cents
        Money.count += 1

    def __eq__(self, other):
        return self.cents == other.cents

    def __lt__(self, other):
        return self.cents < other.cents

    def __str__(self):
        return '$' + str(self.cents // 100) + '.' + str(self.cents % 100).zfill(2)

