solution:
class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def dist(self, other):
        return ((self.x - other.x) ** 2 + (self.y - other.y) ** 2) ** 0.5

class Polyline:
    def __init__(self, points):
        self.points = points

    def length(self):
        total = 0.0
        for i in range(len(self.points) - 1):
            total += self.points[i].dist(self.points[i + 1])
        return total
